{
  "hypotheses": [
    {
      "id": "h1",
      "kind": "feature_code",
      "rationale": "Возраст здания (2015 - year_built) и суммарные градусо-дни напрямую связаны с энергопотреблением; явное взаимодействие может уловить, что старые здания в более суровом климате потребляют больше, что не всегда хорошо извлекается деревом из отдельных колонок.",
      "patch": {
        "features.custom": [
          "+fe_building_age_total_dd"
        ]
      },
      "feature_spec": "fe_building_age_total_dd = (2015 - year_built) * (heating_degree_days_c + cooling_degree_days_c); если year_built <= 0 или NaN, результат NaN",
      "expected": "Снижение RMSE за счет более явного взаимодействия возраста здания и погодной нагрузки.",
      "cost": "low"
    },
    {
      "id": "h2",
      "kind": "config",
      "rationale": "facility_type имеет высокую важность, но native-кодирование не дает агрегированных характеристик по типу; group_stats добавит средние и дисперсии площади, рейтинга и погодных нагрузок внутри назначения, что может помочь разделить здания с одинаковым типом, но разными масштабами и климатом.",
      "patch": {
        "features.builtin": [
          "+group_stats"
        ],
        "features.group_by": [
          "facility_type"
        ],
        "features.group_cols": [
          "floor_area",
          "energy_star_rating",
          "heating_degree_days_c",
          "cooling_degree_days_c",
          "ELEVATION"
        ]
      },
      "feature_spec": null,
      "expected": "Снижение RMSE за счет дополнительных агрегатов по типу здания.",
      "cost": "medium"
    },
    {
      "id": "h3",
      "kind": "model",
      "rationale": "Текущий XGBoost с max_depth=7 и умеренной регуляризацией может переобучаться на редких уровнях facility_type и погодных признаках; уменьшение глубины, увеличение min_child_weight и reg_lambda должно улучшить обобщение.",
      "patch": {
        "model.params.max_depth": 6,
        "model.params.min_child_weight": 10,
        "model.params.reg_lambda": 5
      },
      "feature_spec": null,
      "expected": "Снижение RMSE за счет уменьшения переобучения.",
      "cost": "low"
    },
    {
      "id": "h4",
      "kind": "feature_code",
      "rationale": "Сезонный размах температур (июльский максимум минус январский минимум) отражает амплитуду HVAC-нагрузки, которая не полностью покрыта HDD/CDD и может быть полезна для зданий с разными режимами использования.",
      "patch": {
        "features.custom": [
          "+fe_temp_range"
        ]
      },
      "feature_spec": "fe_temp_range = july_max_temp_c - january_min_temp_c",
      "expected": "Снижение RMSE за счет явного сезонного размаха температур.",
      "cost": "low"
    },
    {
      "id": "h5",
      "kind": "config",
      "rationale": "Частотное кодирование категорий может дать XGBoost более стабильные числовые признаки для редких уровней facility_type и State_Factor, не используя target encoding, который уже ухудшил метрику.",
      "patch": {
        "features.builtin": [
          "+freq_enc"
        ]
      },
      "feature_spec": null,
      "expected": "Снижение RMSE за счет более стабильного кодирования категорий.",
      "cost": "low"
    }
  ]
}
